const input = $input.first().json;

// WEBHOOK AUTH: URL Token dogrulama
const AUTH_TOKEN = 'F9a2Km7Qx8LpN3vB7jR5wY2tH6dK4mS';
const receivedToken = (input.query?.token || input.headers?.token || '');
if (AUTH_TOKEN && receivedToken !== AUTH_TOKEN) {
  console.error('[Webhook Auth] Basarisiz: Gecersiz token');
  return [{ json: { _action: 'auth_failed', reason: 'invalid_token' } }];
}

// Gecerli webhook
return [{ json: input }];

const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;

const rawJid = input.body.data.key.remoteJid || '';
const senderNumber = rawJid.replace('@s.whatsapp.net', '').replace('@g.us', '').replace('@lid', '');
const senderName = input.body.data.pushName || senderNumber;
const messageText = (input.body.data.message?.conversation
  || input.body.data.message?.extendedTextMessage?.text
  || input.body.data.message?.imageMessage?.caption
  || '[Medya]').trim();

const messageId = String(input.body.data.key.id || '');
const fromMe = input.body.data.key.fromMe === true;
const now = Date.now();
const maxMessages = 30;

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};
if (!staticData._seenMessageIds) staticData._seenMessageIds = {};

// Deduplication Check (TTL + Size Limit)
if (messageId && staticData._seenMessageIds[messageId]) {
  return [{ json: { _action: 'ignore', reason: 'duplicate_message', messageId } }];
}
if (messageId) {
  staticData._seenMessageIds[messageId] = now;
  const seenTtlMs = 6 * 60 * 60 * 1000; // 6 saat TTL
  const cleanupIntervalMs = 5 * 60 * 1000;
  const lastCleanupAt = Number(staticData._lastSeenCleanupAt || 0);
  if (now - lastCleanupAt >= cleanupIntervalMs) {
    for (const [id, seenAt] of Object.entries(staticData._seenMessageIds)) {
      if (now - Number(seenAt || 0) > seenTtlMs) delete staticData._seenMessageIds[id];
    }
    staticData._lastSeenCleanupAt = now;
  }
  const ids = Object.keys(staticData._seenMessageIds);
  if (ids.length > 3000) {
    ids.sort((a, b) => staticData._seenMessageIds[a] - staticData._seenMessageIds[b])
       .slice(0, ids.length - 2500)
       .forEach(id => delete staticData._seenMessageIds[id]);
  }
}

// === YETKİLİ KULLANICI KONTROLÜ (fromMe veya Yönetici Numaraları) ===
const ownerNumbers = ['905052237182', '905306056066', '905363955525'];
const isAuthorized = fromMe || ownerNumbers.includes(senderNumber);

// === ++/-- KOMUTLARI: YALNIZCA YETKİLİ İSE KOMUT OLARAK İŞLE (CMD-001) ===
if (isAuthorized && messageText === '++') {
  staticData._manualModes[senderNumber] = true;
  staticData._manualModes = Object.assign({}, staticData._manualModes);
  delete staticData._batches[senderNumber];
  return [{ json: {
    _action: 'command',
    senderNumber: senderNumber,
    command: 'paused',
    commandMessageId: messageId,
    commandFromMe: fromMe,
    commandRemoteJid: rawJid,
    commandParticipant: input.body.data.key.participant || '',
    bildirim: 'Sistem Manuel De - ' + senderName + ' (' + senderNumber + ')'
  }}];
}

if (isAuthorized && messageText === '--') {
  delete staticData._manualModes[senderNumber];
  staticData._manualModes = Object.assign({}, staticData._manualModes);
  return [{ json: {
    _action: 'command',
    senderNumber: senderNumber,
    command: 'resumed',
    commandMessageId: messageId,
    commandFromMe: fromMe,
    commandRemoteJid: rawJid,
    commandParticipant: input.body.data.key.participant || '',
    bildirim: 'Sistem Otomatik - ' + senderName + ' (' + senderNumber + ')'
  }}];
}

if (fromMe || staticData._manualModes[senderNumber] === true) {
  return [{ json: { _action: 'ignore' } }];
}

// === IDL-002: Müşteriden yeni mesaj (!fromMe) geldiyse idle sayacını sil ===
if (!fromMe && staticData._lastReply && staticData._lastReply[senderNumber]) {
  delete staticData._lastReply[senderNumber];
}

// === BATCH TOPLAMA (State Isolation ile) ===
if (!staticData._batches[senderNumber]) {
  staticData._batches[senderNumber] = {
    pendingMessages: [],
    processingMessages: [],
    pendingStartedAt: now,
    lastMessageAt: now,
    processingStartedAt: null,
    processingToken: null,
    senderName: senderName,
    processing: false,
    hasImages: false
  };
}

const batch = staticData._batches[senderNumber];
if (!Array.isArray(batch.pendingMessages)) batch.pendingMessages = [];
if (!Array.isArray(batch.processingMessages)) batch.processingMessages = [];

if (batch.pendingMessages.length >= maxMessages) {
  return [{ json: { _action: 'spam_limit', senderNumber, senderName } }];
}

const hasImage = input.body.data.message?.imageMessage ? true : false;
if (hasImage) batch.hasImages = true;

if (!batch.pendingStartedAt || batch.pendingMessages.length === 0) {
  batch.pendingStartedAt = now;
}

batch.pendingMessages.push({
  id: messageId,
  text: messageText,
  type: hasImage ? 'image' : 'text',
  timestamp: now,
  time: new Date(now).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }),
  mediaUrl: input.body.data.message?.imageMessage?.url || null,
  mediaKey: input.body.data.message?.imageMessage?.mediaKey || null,
  mimetype: input.body.data.message?.imageMessage?.mimetype || null
});

batch.lastMessageAt = now;
batch.senderName = senderName;

// BAT-001: Fast-path bozukluğunu engelle, tüm batch işlemlerini Stale Batch Check (claimBatch) yapsın
return [{ json: {
  _action: batch.processing ? 'queued_during_processing' : 'queued',
  senderNumber,
  senderName,
  pendingCount: batch.pendingMessages.length,
  processing: batch.processing === true
}}];

const input = $input.item.json;

const allMessages  = String(input.allMessagesText || '');
const messageCount = Number(input.messageCount || 0);
const senderName   = String(input.senderName || '');

// FİLTRE KODU PATTERN TARAMASI (REG-001, REG-002, REG-003)
const codePatterns = [
  /\b(?:MANN[-\s]?)?(?:W|C|HU|WK|PU|PL|FP|CU|CUK|H)\s?\d{1,4}(?:\s?\d{2,4})?(?:\s?[\/\-]\s?\d{1,2})?(?:\s?[xXzZ])?\b/gi,
  /\b(?:FILTRON[-\s]?)?(?:OP|P|OS|OW|PS|WS|AS|AP|L|LS)\s?\d{3,4}(?:\s?[\/\-]\s?\d{1,2})?\b/gi,
  /\b(?:UFI[-\s]?)?\d{2}\.\d{2,3}\.\d{2}(?:[\/\-]\d)?\b/gi,
  /\b(?:HENGST[-\s]?)?E\s?\d{2,4}[A-Z0-9]*(?:\s?D?\s?\d{2,3}[A-Z]?)?\b/gi,
  /\b(?:PURFLUX[-\s]?)?LS\s?\d{3,4}(?:[\/\-]\d{1,2})?\b/gi,
  /\b(?:MAHLE[-\s]?)?(?:OX|OC|KC|KL|KX|PI|LS|W)\s?\d{2,4}[A-Z]?\b/gi,
  /\b(?:FILTORQ[-\s]?)?[A-Z]{1,3}\s?\d{3,4}(?:[\/\-]\d{1,2})?\b/gi,
  /\b[A-Z]{1,4}\s?\d{2,5}[\/\-]\d{2,5}(?:\s?(?:KIT|SET|PRO))?\b/gi,
  /\b(?!(?:201[0-9]|202[0-6])\b)\d{3,4}\s?[\/\-]\s?\d{1,2}\b/g
];

const rawCandidates = [];
for (const pattern of codePatterns) {
  pattern.lastIndex = 0;
  let match;
  while ((match = pattern.exec(allMessages)) !== null) {
    const code = match[0].trim().toUpperCase();
    // REG-003: Araç model yılları (2010..2026) ve 4 karakterden kısa kodları ele
    if (code.length >= 4 && !/\b20(1[0-9]|2[0-6])\b/.test(code)) {
      rawCandidates.push(code);
    }
  }
}

// REG-004: Sub-part tekilleştirme (En uzun koddan başla, kapsanan alt parçaları atla)
const uniqueCandidates = [...new Set(rawCandidates)].sort((a, b) => b.length - a.length);
const detectedCodes = [];
for (const code of uniqueCandidates) {
  if (!detectedCodes.some(selected => selected.includes(code))) {
    detectedCodes.push(code);
  }
}

// ARAÇ VE VIN TARAMASI
const vehicleHints = [];
const msgLower = allMessages.toLowerCase();
const vehicleKeywords = ['fiat','volkswagen','vw','renault','ford','toyota','hyundai','opel','peugeot','citroen','bmw','mercedes','audi','seat','skoda','egea','doblo','golf','passat','polo','clio','megane','tdi','multijet','dci','1.3','1.6','1.4','2010','2011','2012','2013','2014','2015','2016','2017','2018','2019','2020','2021','2022','2023'];
for (const kw of vehicleKeywords) {
  if (msgLower.includes(kw)) vehicleHints.push(kw);
}
const vinPattern = /\b[A-HJ-NPR-Z0-9]{17}\b/gi;
const detectedVINs = [];
let vinMatch;
while ((vinMatch = vinPattern.exec(allMessages)) !== null) {
  detectedVINs.push(vinMatch[0].toUpperCase());
}

let prompt = '═══ BAĞLAM BİLGİSİ (Sistem Taraması) ═══\n' +
  'Müşteri adı: ' + senderName + '\n' +
  'Batch mesaj sayısı: ' + messageCount + '\n';
if (detectedCodes.length > 0) prompt += '⚠️ TESPİT EDİLEN FİLTRE KODLARI: ' + detectedCodes.join(', ') + '\n';
if (detectedVINs.length > 0) prompt += '🔑 TESPİT EDİLEN ŞASİ NUMARASI: ' + detectedVINs.join(', ') + '\n';
if (vehicleHints.length > 0) prompt += '🚗 ARAÇ İPUCU KELİMELERİ: ' + [...new Set(vehicleHints)].join(', ') + '\n';
// VIS-001: Görsel işleme modelinin bulunmadığına dair net talimat
if (input.hasImages) prompt += '📸 MÜŞTERİ GÖRSEL GÖNDERDİ: Sistemde henüz doğrudan görsel işleme (vision model) aktif değildir. Görselden parça kodu veya marka KESİNLİKLE UYDURMA/HALÜSİNASYON YAPMA! Eğer mesaj metninde net bir parça kodu yoksa, replyDraft içinde tam olarak "Görsel ulaştı. Ürün üzerindeki marka ve parça kodunu yazılı olarak paylaşabilir misiniz?" cevabını ver (ve codeStatus: "uncertain", source: "vision" olarak işaretle).\n';
prompt += '═══════════════════════════════════════\n\n';
prompt += 'Yeni müşteri mesajları:\n' + allMessages;

return {
  json: {
    senderNumber: input.senderNumber,
    senderName: input.senderName,
    allMessagesText: input.allMessagesText,
    messageCount: input.messageCount,
    batchToken: input.batchToken,
    detectedCodes,
    detectedVINs,
    hasImages: input.hasImages || false,
    _prompt: prompt
  }
};

const staticData = $getWorkflowStaticData('global');
const currentInput = $input.item.json;
const rawAiOutput = currentInput?.output || currentInput?.aiResult || '';
const aiOutput = typeof rawAiOutput === 'string' ? rawAiOutput : JSON.stringify(rawAiOutput);

let senderNumber = '';
let senderName = '';
let allMessagesText = '';
let batchToken = '';
let detectedCodes = [];
try {
  const sc = $('Store Context').item.json;
  senderNumber = String(sc.senderNumber || '');
  senderName = String(sc.senderName || senderNumber || 'Bilinmeyen müşteri');
  allMessagesText = String(sc.allMessagesText || '');
  batchToken = String(sc.batchToken || '');
  if (Array.isArray(sc.detectedCodes)) detectedCodes = sc.detectedCodes;
} catch(e) {
  console.error('[Parse AI Output] Store Context okunamadı:', e?.message || e);
  throw new Error('Parse AI Output gerekli Store Context verisine ulaşamadı');
}

if (!staticData._unclearCounts) staticData._unclearCounts = {};
if (!staticData._batches) staticData._batches = {};
if (!staticData._adminNotifications) staticData._adminNotifications = {};

const batch = staticData._batches[senderNumber];
const validClaim = Boolean(batch && batch.processing === true && batch.processingToken === batchToken);

if (!validClaim && senderNumber) {
  return { json: {
    senderNumber, senderName, batchToken, action: 'ignore', intent: 'other', caseType: 'other',
    cevap: '', missingFields: [], confidence: 0, handoffReason: 'Geçersiz veya süresi dolmuş işlem yutuldu',
    notifyAdmins: false, validClaim: false, bildirim: ''
  }};
}

let parsed = null;
if (typeof rawAiOutput === 'object' && rawAiOutput !== null) {
  parsed = rawAiOutput;
} else {
  try {
    const cleaned = aiOutput.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e1) {
    try {
      const match = aiOutput.match(/\{[\s\S]*\}/);
      if (match) parsed = JSON.parse(match[0]);
    } catch(e2) {
      console.error('[Parse AI Output] AI JSON ayrıştırılamadı:', e1?.message || e1, e2?.message || e2);
    }
  }
}

if (!parsed) {
  return { json: {
    senderNumber, senderName, batchToken, action: 'handoff', intent: 'unclear', caseType: 'unclear',
    cevap: 'Talebinizi ilgili ekibimize aktarıyorum. Yetkilimiz sizinle ilgilenecektir.',
    missingFields: [], confidence: 0, handoffReason: 'AI JSON ayrıştırma hatası',
    notifyAdmins: true, validClaim: true, pauseAutomation: true,
    bildirim: `⚠️ AI ÇIKTISI AYRIŞTIRILAMADI\nMüşteri: ${senderName} (${senderNumber})\nMesaj: ${allMessagesText}`
  }};
}

const intent = String(parsed.intent || 'other').trim();
let caseType = String(parsed.caseType || intent || 'other').trim();
const entities = parsed.entities || {};
let replyDraft = String(parsed.replyDraft || parsed.reply || parsed.cevap || '').trim();
// Boş cevap koruması (Fallback)
if (!replyDraft || replyDraft.trim() === '') {
  if (caseType === 'exact_code_price_stock' || caseType === 'cross_reference') {
    replyDraft = 'Talebiniz alınmıştır. Güncel stok ve fiyat kontrolü yapılarak size bilgi verilecektir.';
  } else if (caseType === 'exact_code_compatibility' || caseType === 'vehicle_based_search') {
    replyDraft = 'Araç uyumluluk kontrolünüz ilgili birimimize iletilmiştir, yetkilimiz tarafından bilgilendirileceksiniz.';
  } else if (caseType === 'partial_code') {
    replyDraft = 'İletmiş olduğunuz kod tam olarak anlaşılamadı veya eksik. Filtre kodunun tamamını veya aracınızın detaylarını paylaşabilir misiniz?';
  } else if (caseType === 'greeting') {
    replyDraft = 'Merhaba! Size nasıl yardımcı olabilirim? (Lütfen filtre kodunuzu veya aracınızın motor hacmi ve beygir gücü/şasi numarasını belirtin)';
  } else if (caseType === 'unclear') {
    replyDraft = 'İfadenizi tam anlayamadım, ilgili uzmanımıza aktarıyorum.';
  } else {
    replyDraft = 'Talebiniz müşteri temsilcimize aktarılmıştır.';
  }
}
const missingFields = Array.isArray(parsed.missingFields) ? parsed.missingFields.slice(0, 10) : [];
const verification = parsed.verification || {};

// P0-1: Quantity Provenance
if (entities.quantity && entities.quantity !== 'Belirtilmedi') {
  const nums = String(entities.quantity).match(/\d+/g);
  if (nums && nums.length > 0) {
    const num = nums[0];
    const qtyRegex = new RegExp(`\\b${num}\\s*(?:adet|tane|pcs|x)|(?:x)\\s*${num}\\b`, 'i');
    const textHasNumContext = qtyRegex.test(allMessagesText);
    if (!textHasNumContext) entities.quantity = 'Belirtilmedi';
  } else {
  }
}

// P0-2: Granular Vehicle Provenance (brand/model/year/engine/vin)
if (Array.isArray(entities.vehicles)) {
  entities.vehicles = entities.vehicles.map(v => {
    const textLower = allMessagesText.toLowerCase();
    if (typeof v === 'object' && v) {
      if (v.brand && !textLower.includes(String(v.brand).toLowerCase())) v.brand = null;
      if (v.model && !textLower.includes(String(v.model).toLowerCase())) v.model = null;
      if (v.year && !allMessagesText.includes(String(v.year))) v.year = null;
      if (v.engine && !textLower.includes(String(v.engine).toLowerCase())) v.engine = null;
      if (v.horsePower && !textLower.includes(String(v.horsePower).toLowerCase())) v.horsePower = null;
      if (v.vin && !textLower.includes(String(v.vin).toLowerCase())) v.vin = null;
      if (!v.brand && !v.model && !v.year && !v.engine && !v.vin && !v.raw) return null;
      if (v.raw) {
        const yearMatch = String(v.raw).match(/\b(19\d\d|20\d\d)\b/);
        if (yearMatch && !allMessagesText.includes(yearMatch[1])) v.raw = null;
        const rawWords = String(v.raw).toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\s+/).filter(w => w.length > 2);
        if (v.raw && rawWords.length > 0 && !rawWords.every(w => textLower.includes(w))) v.raw = null;
      }
      return v;
    } else {
      let str = String(v);
      const yearMatch = str.match(/\b(19\d\d|20\d\d)\b/);
      if (yearMatch && !allMessagesText.includes(yearMatch[1])) return null;
      const engineMatch = str.match(/\b(\d\.\d)\b/);
      if (engineMatch && !allMessagesText.includes(engineMatch[1])) return null;
      const words = str.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\s+/).filter(w => w.length > 2);
      if (words.length > 0 && !words.every(w => textLower.includes(w))) return null;
      return v;
    }
  }).filter(Boolean);
}

// P1-5: Preferred Brands
const knownBrands = ['MANN', 'BOSCH', 'FILTRON', 'UFI', 'HENGST', 'PURFLUX', 'MAHLE', 'FILTORQ'];
const textUpper = allMessagesText.toUpperCase();
const detectedBrands = knownBrands.filter(b => textUpper.includes(b));
if (detectedBrands.length > 0) {
  let existing = Array.isArray(entities.preferredBrands) ? entities.preferredBrands : [];
  entities.preferredBrands = [...new Set([...existing.map(x=>String(x).toUpperCase()), ...detectedBrands])];
}

// ═══════════════════════════════════════════════════════════════
// SCH-001: CASE_TYPE ALLOWLIST & SCHEMA ENFORCEMENT
// ═══════════════════════════════════════════════════════════════
const validCaseTypes = [
  'exact_code_price_stock',
  'exact_code_compatibility',
  'cross_reference',
  'partial_code',
  'vehicle_based_search',
  'non_product',
  'unclear',
  'greeting'
];

let isSchemaViolation = false;
if (!validCaseTypes.includes(caseType)) {
  isSchemaViolation = true;
  caseType = 'unclear';
}

// ═══════════════════════════════════════════════════════════════
// DÜZELTME 1: CONFİDENCE — İKİ TİP DESTEĞİ (number + object)
// ═══════════════════════════════════════════════════════════════
let confidenceValue = 0;
const rawConfidence = parsed.confidence;
if (typeof rawConfidence === 'number' && Number.isFinite(rawConfidence)) {
  confidenceValue = rawConfidence;
} else if (typeof rawConfidence === 'object' && rawConfidence !== null) {
  const vals = [
    Number(rawConfidence.intent || 0),
    Number(rawConfidence.caseType || 0),
    Number(rawConfidence.entityExtraction || 0)
  ].filter(v => Number.isFinite(v));
  confidenceValue = vals.length > 0 ? Math.min(...vals) : 0;
}
confidenceValue = Math.max(0, Math.min(1, confidenceValue));

// ═══════════════════════════════════════════════════════════════
// GRD-002: VERIFICATION HARD-RESET (No External Verification Node)
// ═══════════════════════════════════════════════════════════════
const hasExternalVerification = Boolean(currentInput?.externalVerificationVerified === true);
if (!hasExternalVerification) {
  verification.priceVerified = false;
  verification.stockVerified = false;
  verification.compatibilityVerified = false;
  verification.catalogVerified = false;
  verification.dataSource = 'unverified_ai_output';
}

// ═══════════════════════════════════════════════════════════════
// GRD-003: LAYER 2 GUARDRAIL (DOĞRUDAN UYUMLULUK VE STOK GARANTİSİ INTERCEPTOR)
// ═══════════════════════════════════════════════════════════════
let guardrailTriggered = false;
let triggeredRule = '';

const PRICE_PATTERN = /(?:₺\s*\d+(?:[\.,]\d+)?|\d+(?:[\.,]\d+)?\s*(?:TL|₺|TRY|Lira)|(?:fiyat[ıi]?|ücret|bedel|tutar)\s*[:=]?\s*\d{2,}|(?:yüz|bin|milyon)\s+(?:lira|tl))/i;
const COMPAT_GUARANTEE = /(?:(?:kesin(?:likle)?|garanti|tam(?:amen)?|net|birebir|%100|%99)\s*(?:uy(?:ar|umlu|um|gundur)?|olur|oturur|tak[ıi]l[ıi]r|geçer)|(?:ara(?:c|ç|c[ıi]n[ıi]z)a?|motor(?:a|u|unuza)?|model(?:e|inize)?)\s+(?:tam\s+)?(?:uyar|uygundur|uyumludur|olur)|\b(?:uygundur|uyumludur)\b)/i;
const STOCK_GUARANTEE = /(?:stok(?:ta|larımızda|umuzda|larda)?|elimizde|depo(?:muz)?da)\s+(?:mevcut(?:tur|dur)?|var(?:dır)?|bulun(?:uyor|maktad[ıi]r)|uygun(?:dur)?|mevcuttur)/i;
const BANNED_PHRASES = [
  'stokta var',
  'stoklarımızda mevcut',
  'elimizde mevcut',
  'kesin uyar',
  'uyumludur',
  'uygundur',
  'aracınıza uyar',
  'aracınızla uyumludur',
  'aracınız için uygundur',
  'birebir muadilidir',
  'yerine kullanabilirsiniz',
  'garanti uyar',
  'garanti uygundur',
  'mevcut görünüyor',
  'sorunsuz kullanabilirsiniz',
  'birebir karşılığıdır',
  'tam karşılığıdır',
  'direkt takılır',
  'rahatlıkla kullanabilirsiniz'
];

const UNSAFE_CONTENT = /(?:https?:\/\/|www\.)[^\s]+|şifre|kredi\s?kart|\bcvv\b|\botp\b/i;
if (UNSAFE_CONTENT.test(replyDraft)) {
  guardrailTriggered = true;
  triggeredRule = 'Güvenli olmayan bağlantı veya hassas veri talebi';
} else if (verification.priceVerified !== true && PRICE_PATTERN.test(replyDraft)) {
  guardrailTriggered = true;
  triggeredRule = 'Doğrulanmamış rakamsal fiyat/TL halüsinasyonu';
} else if (verification.stockVerified !== true || verification.compatibilityVerified !== true) {
  if (COMPAT_GUARANTEE.test(replyDraft) || STOCK_GUARANTEE.test(replyDraft)) {
    guardrailTriggered = true;
    triggeredRule = 'Yasaklı stok/uyumluluk garantisi';
  } else {
    const replyLower = replyDraft.toLocaleLowerCase('tr-TR');
    for (const phrase of BANNED_PHRASES) {
      if (replyLower.includes(phrase.toLocaleLowerCase('tr-TR'))) {
        guardrailTriggered = true;
        triggeredRule = `Yasaklı stok/uyumluluk garantisi ('${phrase}')`;
        break;
      }
    }
  }
}

if (guardrailTriggered) {
  replyDraft = 'Ürünün güncel stok, fiyat ve teknik uygunluk bilgisi yetkilimiz tarafından kontrol edilerek size iletilecektir.';
}

// ═══════════════════════════════════════════════════════════════
// PRV-001: PROVENANCE CHECK (Katalog/Mesaj Dışı Parça Kodu Halüsinasyon Kontrolü)
// ═══════════════════════════════════════════════════════════════
const extractedCodeItems = Array.isArray(entities.productCodes) ? entities.productCodes : [];
if (extractedCodeItems.length > 0) {
  const rawCodes = extractedCodeItems.map(c => typeof c === 'object' ? (c.code || c.raw) : c).filter(Boolean);
  const sorted = [...new Set(rawCodes)].sort((a, b) => String(b).length - String(a).length);
  const deduped = [];
  for (const c of sorted) {
    if (!deduped.some(selected => String(selected).includes(String(c)))) deduped.push(c);
  }
  entities.productCodes = deduped;
}
let provenanceViolation = false;
let unverifiedCode = '';

if (extractedCodeItems.length > 0 && intent !== 'greeting' && caseType !== 'greeting') {
  const normalizeForMatch = (str) => String(str || '').replace(/[\s\-\/\._\\]+/g, '').toLocaleLowerCase('tr-TR');
  const normAllMessages = normalizeForMatch(allMessagesText);
  const normDetected = (Array.isArray(detectedCodes) ? detectedCodes : []).map(c => normalizeForMatch(c));

  for (const item of extractedCodeItems) {
    const rawVal = typeof item === 'object' && item !== null ? String(item.raw || '') : String(item || '');
    const codeVal = typeof item === 'object' && item !== null ? String(item.code || '') : String(item || '');

    const candidates = [rawVal, codeVal].filter(s => s && s.trim().length >= 3);
    if (candidates.length === 0) continue;

    let isProven = false;
    for (const cand of candidates) {
      const normCand = normalizeForMatch(cand);
      if (!normCand || normCand.length < 3) continue;

      if (allMessagesText.toLocaleLowerCase('tr-TR').includes(cand.toLocaleLowerCase('tr-TR')) ||
          normAllMessages.includes(normCand)) {
        isProven = true;
        break;
      }

      if (normDetected.some(d => d.includes(normCand) || normCand.includes(d))) {
        isProven = true;
        break;
      }
    }

    if (!isProven) {
      provenanceViolation = true;
      unverifiedCode = candidates[0] || 'Bilinmeyen Kod';
      break;
    }
  }
}

// ═══════════════════════════════════════════════════════════════
// POL-003: ARAÇ BİLGİSİ TAM OLMA (COMPLETENESS) KONTROL FONKSİYONU
// ═══════════════════════════════════════════════════════════════
function isVehicleComplete(vehicles) {
  if (!Array.isArray(vehicles) || vehicles.length === 0) return false;
  const vinStringMatch = /\b[A-HJ-NPR-Z0-9]{17}\b/i;
  const engineRegex = /(?:\b\d+[\.,]\d+\s*(?:td[iı]|ts[iı]|cdti|hd[iı]|tdci|mjet|tfsi|vvt-?i|l|lt|cc)?\b|\b\d+\s*(?:hp|bg|ps|kw|cc)\b|\b(?:td[iı]|ts[iı]|cdti|hd[iı]|tdci|mjet|tfsi)\b)/i;

  for (const v of vehicles) {
    if (typeof v === 'string') {
      const trimmed = v.trim();
      if (vinStringMatch.test(trimmed)) return true;
      const hasYear = /\b(?:19|20)\d{2}\b/.test(trimmed);
      const hasEngine = engineRegex.test(trimmed);
      const words = trimmed.split(/\s+/).filter(Boolean);
      if (hasYear && hasEngine && words.length >= 4) return true;
    } else if (typeof v === 'object' && v !== null) {
      const vin = String(v.vin || v.chassis || v.sasi || '').trim();
      if (vin.length === 17 || vinStringMatch.test(vin)) return true;
      const fullObjStr = Object.values(v).join(' ');
      if (vinStringMatch.test(fullObjStr)) return true;
      const brand = String(v.brand || v.marka || '').trim();
      const model = String(v.model || '').trim();
      const year = String(v.year || v.yil || '').trim();
      const engine = String(v.engine || v.motor || v.engineCode || v.motorKodu || v.hp || v.power || v.cc || v.spec || '').trim();
      const hasBrandModelYear = Boolean(brand && model && year && /\d{4}/.test(year));
      const hasEngineSpec = Boolean(engine) || engineRegex.test(fullObjStr);
      if (hasBrandModelYear && hasEngineSpec) return true;
    }
  }
  return false;
}

