const staticData = $getWorkflowStaticData('global');
const now = Date.now();

const BATCH_WINDOW_MS    = 120 * 1000;     // İlk mesajdan itibaren sabit 120 sn toplama penceresi
const PROCESSING_TIMEOUT = 2 * 60 * 1000;  // 2 dk AI işlem timeout recovery

if (!staticData._batches) staticData._batches = {};
if (!staticData._manualModes) staticData._manualModes = {};
for (const [number, enabled] of Object.entries(staticData._manualModes)) {
  if (enabled !== true) delete staticData._manualModes[number];
}

const ready = [];

for (const [number, rawBatch] of Object.entries(staticData._batches)) {
  const batch = rawBatch || {};
  if (!Array.isArray(batch.pendingMessages)) batch.pendingMessages = Array.isArray(batch.messages) ? batch.messages : [];
  if (!Array.isArray(batch.processingMessages)) batch.processingMessages = [];
  delete batch.messages;

  if (staticData._manualModes[number] === true) {
    delete staticData._batches[number];
    continue;
  }

  // Yarım kalan AI işlemini yeniden kuyruğa al
  if (batch.processing === true && batch.processingStartedAt && (now - Number(batch.processingStartedAt) > PROCESSING_TIMEOUT)) {
    batch.pendingMessages = [...batch.processingMessages, ...batch.pendingMessages];
    batch.processingMessages = [];
    batch.processing = false;
    batch.processingStartedAt = null;
    batch.processingToken = null;
  }

  if (batch.processing === true) continue;
  if (!batch.pendingMessages.length) {
    delete staticData._batches[number];
    continue;
  }

  const startTime = Number(batch.pendingStartedAt || batch.startTime || now);
  const totalTime = now - startTime;

  const isWindowReached = totalTime >= BATCH_WINDOW_MS;

  if (isWindowReached) {
    ready.push({ number, lastTime: Number(batch.lastMessageAt || batch.lastMessageTime || now), batch, triggeredBy: '120_second_window' });
  }
}

ready.sort((a, b) => a.lastTime - b.lastTime);
if (ready.length === 0) {
  return [{ json: { senderNumber: '', messageCount: 0, _ready: false } }];
}

const outputItems = [];
const batchLimit = Math.min(ready.length, 10);
for (let i = 0; i < batchLimit; i++) {
  const selected = ready[i];
  const { number, batch } = selected;
  const processingMessages = batch.pendingMessages.splice(0);
  const processingToken = number + '-' + now + '-' + Math.random().toString(36).slice(2, 10);

  batch.processingMessages = processingMessages;
  batch.processing = true;
  batch.processingStartedAt = now;
  batch.processingToken = processingToken;
  batch.pendingStartedAt = null;

  const allMessagesText = processingMessages
    .map((message, index) => `${index + 1}. [${message.time || ''}] ${message.text}`)
    .join('\n');

  const hasImages = processingMessages.some(m => m.type === 'image');
  const imageMessages = processingMessages
    .filter(m => m.type === 'image' && m.mediaUrl)
    .map(m => ({ mediaUrl: m.mediaUrl, mediaKey: m.mediaKey, mimetype: m.mimetype }));

  outputItems.push({
    json: {
      _ready: true,
      senderNumber: number,
      senderName: batch.senderName || number,
      messageCount: processingMessages.length,
      allMessagesText,
      batchToken: processingToken,
      hasImages,
      imageMessages
    }
  });
}
return outputItems;

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const idleAlertMs = 10 * 60 * 1000;

if (!staticData._lastReply) staticData._lastReply = {};
const alerts = [];
for (const [number, lastReplyTime] of Object.entries(staticData._lastReply)) {
  if (now - lastReplyTime >= idleAlertMs) {
    alerts.push({
      json: {
        senderNumber: number,
        bildirim: `Sessiz müşteri - ${number} - 10 dakikadır yanıt vermiyor`,
        _idleAlert: true
      }
    });
    delete staticData._lastReply[number];
  }
}
if (alerts.length === 0) return [{ json: { _idleAlert: false } }];
return alerts;
